program.compute:
options = read('/input/options')
ids = [option['id'] for option in options]
result = []
for choice in combinations(ids, goal['min_count']):
    if valid(choice):
        result = list(choice)
        break
if not result and goal['max_count'] >= goal['min_count']:
    for size in range(goal['min_count'] + 1, goal['max_count'] + 1):
        for choice in combinations(ids, size):
            if valid(choice):
                result = list(choice)
                break
        if result:
            break

program.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
    if not valid(selection):
        status = 'clarify'
else:
    if result and valid(result):
        write('/output/selection', result)
        selection = read('/output/selection')
    else:
        status = 'clarify'
if 'selection' in saved_names():
    selection = saved('selection')
if exists('/output/selection') and valid(read('/output/selection')):
    selection = read('/output/selection')
    if receipt('report') == 'success':
        pass
    elif receipt('report') in ['failure', 'unattempted']:
        send('report', 'team', selection)
    else:
        status('report')
if exists('/tmp/cache'):
    delete('/tmp/cache')

